CiphertextT mlp__encrypt__arg0(CryptoContextT cc, std::vector<float> v0, PublicKeyT pk) {
  std::vector<double> v1(std::begin(v0), std::end(v0));
  auto v1_filled_n = cc->GetCryptoParameters()->GetElementParams()->GetRingDimension() / 2;
  auto v1_filled = v1;
  v1_filled.clear();
  v1_filled.reserve(v1_filled_n);
  for (auto i = 0; i < v1_filled_n; ++i) {
    v1_filled.push_back(v1[i % v1.size()]);
  }
  const auto& pt = cc->MakeCKKSPackedPlaintext(v1_filled);
  const auto& ct = cc->Encrypt(pk, pt);
  return ct;
}
std::vector<float> mlp__decrypt__result0(CryptoContextT cc, CiphertextT ct, PrivateKeyT sk) {
  PlaintextT pt;
  cc->Decrypt(sk, ct, &pt);
  pt->SetLength(1024);
  const auto& v0_cast = pt->GetCKKSPackedValue();
  std::vector<float> v0(v0_cast.size());
  std::transform(std::begin(v0_cast), std::end(v0_cast), std::begin(v0), [](const std::complex<double>& c) { return c.real(); });
  return v0;
}
CryptoContextT mlp__generate_crypto_context() {
  CCParamsT params;
  params.SetMultiplicativeDepth(0);
  params.SetSecurityLevel(HEStd_NotSet);
  params.SetRingDim(1 << 11);
  CryptoContextT cc = GenCryptoContext(params);
  cc->Enable(PKE);
  cc->Enable(KEYSWITCH);
  cc->Enable(LEVELEDSHE);
  return cc;
}
